<?php require dirname(__DIR__).'/bootstrap.php';if(admin()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=db()->prepare('SELECT * FROM users WHERE username=? AND role="admin"');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['uid']=$u['id'];header('Location:index.php');exit;}$err='Sai tài khoản hoặc mật khẩu.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/app.css"></head><body class="auth"><form class="auth-box" method="post"><div class="brand"><span>F</span>FilmNova</div><h1>Quản trị</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="username" value="admin" placeholder="Tài khoản"><input type="password" name="password" placeholder="Mật khẩu"><button class="primary">Đăng nhập</button></form></body></html>
